#!/bin/bash

# This script generates Fjalar's build file valgrind/fjalar/Makefile.am from
# Memcheck's, valgrind/memcheck/Makefile.am, by renaming Memcheck to Fjalar.
# Fjalar's changes to the build are in valgrind/fjalar/fjalar.am, which the
# generated file includes.  Run this script after the Memcheck merge (see
# doc/valgrind-merge.texinfo), and after changing it or fjalar.am.
# Usage: generate-fjalar-makefile.sh [OUTPUT]
# OUTPUT defaults to valgrind/fjalar/Makefile.am.  If any line of the
# generated file may need a change to the renaming, the script prints each
# such line and exits with status 2.  Otherwise it exits with status 0, or
# with status 1 if it fails.

set -e
set -o pipefail
# A failing command, such as sed, may itself exit with status 2.
trap 'exit 1' ERR

top=$(dirname "$0")
output=${1:-$top/valgrind/fjalar/Makefile.am}
# Write to a temporary file, so that a failure leaves OUTPUT unchanged.
tmp=$output.tmp
trap 'rm -f "$tmp"' EXIT

# Fjalar's version is generated instead of patched, because almost every
# line of it renames Memcheck to Fjalar, so most upstream changes would
# conflict.  Fjalar builds every Memcheck source file.
# The sed command renames only Memcheck's program and variable names, not
# file names such as memcheck.h, and it removes the assignment, including
# its continuation lines, that adds Memcheck's docs, which Fjalar lacks, to
# EXTRA_DIST.
{
  echo "## Generated by generate-fjalar-makefile.sh from ../memcheck/Makefile.am."
  echo "## Do not edit this file; put Fjalar's changes in fjalar.am."
  echo
  sed -e 's/memcheck\([-_]\)/fjalar\1/g; s/MEMCHECK_/FJALAR_/g' \
      -e '/^EXTRA_DIST *= *docs\//{:a;/\\$/{N;ba};d}' \
      "$top/valgrind/memcheck/Makefile.am"
  echo
  echo 'include $(srcdir)/fjalar.am'
} > "$tmp"
mv "$tmp" "$output"

# An upstream change that the renaming does not handle needs a change to
# this script.  Conflict markers mean that the Coregrind merge left
# valgrind/memcheck/Makefile.am unresolved.  Each memcheck.h is removed
# before the check, so that the rest of its line is still checked.
problems=$(awk '/^##/ { next }
  { line = tolower($0); gsub(/memcheck\.h/, "", line) }
  line ~ /memcheck|docs\// || /^(<<<<<<<|\|\|\|\|\|\|\||=======|>>>>>>>)/ { print FNR ":" $0 }' "$output")
if [ -n "$problems" ]; then
  echo "Lines of $output that may need a change to the renaming"
  echo "in $0 or a resolution of a conflict:"
  echo "$problems"
  exit 2
fi
